-- MP-0057: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin if not exists(select 1 from public.entities where slug='gabungan-parti-sarawak' and type='alliance') then raise exception 'MP-0057: missing party parent'; end if; if exists(select 1 from public.entities where slug='supp' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='gabungan-parti-sarawak'))) then raise exception 'MP-0057: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'supp','Sarawak United Peoples’ Party','SUPP','government','A component party of Gabungan Parti Sarawak (GPS).','2026-11-10','[{"label": "SUPP · GPS membership and deputy president, June 2026", "url": "https://www.theborneopost.com/2026/06/05/supp-serian-ready-to-defend-seat-says-riot/"}, {"label": "SPR · current registered party emblems", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}]'::jsonb from public.entities parent where parent.slug='gabungan-parti-sarawak' and parent.type='alliance' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='pbb' and type='party') then raise exception 'MP-0057: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='supp' and type='party') then raise exception 'MP-0057: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('rubiah-wang','willie-mongin','richard-riot-jaem') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0057: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kota samarahan','puncak borneo','serian') and slug not in ('rubiah-wang','willie-mongin','richard-riot-jaem')) then raise exception 'MP-0057: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0057:%' and (m.source_type <> 'editorial' or e.slug not in ('rubiah-wang','willie-mongin','richard-riot-jaem') or m.import_key not like 'MP-0057:' || e.slug || ':%')) then raise exception 'MP-0057: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'rubiah-wang','Rubiah Wang','government','Deputy Minister of Rural and Regional Development','Kota Samarahan','Sarawak','Rubiah Wang represents Kota Samarahan, Sarawak, in the Dewan Rakyat. Current role: Deputy Minister of Rural and Regional Development. Affiliated with PBB.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4236','/portraits/rubiah-wang.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P197.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4236"}, {"label": "PBB · current 2025–2028 council", "url": "https://suarasarawak.my/senarai-penuh-majlis-kerja-tertinggi-mkt-pbb-sesi-2025-2028/"}]'::jsonb from public.entities parent where parent.slug='pbb' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'willie-mongin','Willie Mongin','government','Member of the Dewan Rakyat','Puncak Borneo','Sarawak','Willie Mongin represents Puncak Borneo, Sarawak, in the Dewan Rakyat. Affiliated with PBB.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4237','/portraits/willie-mongin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P198.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4237"}, {"label": "PBB · current 2025–2028 council", "url": "https://suarasarawak.my/senarai-penuh-majlis-kerja-tertinggi-mkt-pbb-sesi-2025-2028/"}]'::jsonb from public.entities parent where parent.slug='pbb' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'richard-riot-jaem','Richard Riot Jaem','government','Member of the Dewan Rakyat; Deputy President of SUPP','Serian','Sarawak','Richard Riot Jaem represents Serian, Sarawak, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; Deputy President of SUPP. Affiliated with SUPP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4238','/portraits/richard-riot-jaem.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P199.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4238"}, {"label": "SUPP · deputy president and GPS membership, 5 June 2026", "url": "https://www.theborneopost.com/2026/06/05/supp-serian-ready-to-defend-seat-says-riot/"}]'::jsonb from public.entities parent where parent.slug='supp' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('rubiah-wang','willie-mongin','richard-riot-jaem') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0057: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0057:rubiah-wang:orang-asli-water-projects-2026','Implement 22 Orang Asli village water-supply projects','Infrastructure',null,null,null,'2026-08-04','https://www.bernama.com/bm/news.php?id=2590336',null,null,'Rubiah announced RM3 million under RP1 RMK13 for system upgrades, pipe improvements and tube wells during 2026.','The funding and programme scope are reported. Completed-project counts and physical progress were not verified. The separate number of villages already served and earlier RMK12 spending are not completion of these 22 projects; the annual allocation is not converted into an exact completion deadline.','2026-11-10','editorial',false from public.entities e where e.slug='rubiah-wang' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0057:willie-mongin:biya-jabir-road-tender','Advance the Biya–Jabir road project to tender','Infrastructure','in_progress',null,null,null,null,'2026-09-21','https://www.theborneopost.com/2026/09/21/four-high-impact-projects-underway-for-puncak-borneo-constituency/','Willie reported obtaining federal approval and resolving land-compensation discussions, with the road project recently put out to tender.','A dated procurement-stage report, with funding and implementation shared by the relevant agencies. Tendering does not prove contract award, construction, a finished road or a completion percentage.','2026-11-10','editorial',false from public.entities e where e.slug='willie-mongin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

